// Общие шаги по экранам Banci (по видимым текстам на иврите). Вход — тот аккаунт, под которым уже залогинено приложение.
import { by, assert } from './appium.mjs';

export const TABS = ['בית', 'ילדים', 'היסטוריה', 'חשבון'];

/** Вкладка таб-бара: в RN name бывает «בית» или «בית, tab, 1 of 4». */
export const tab = (name) => `(name == "${name}" OR label == "${name}" OR label BEGINSWITH "${name},") AND (type == "XCUIElementTypeButton" OR type == "XCUIElementTypeOther")`;

/** Приложение на «בית» после перезапуска (вход уже выполнен). */
export async function onHome(app) {
  await app.waitFor(tab('בית'), { timeout: 30000, what: 'таб-бар «בית» (приложение не залогинено? войти вручную)' });
  await app.tap(tab('בית'));
}

/** Элемент таб-бара — самый нижний из совпавших (имя вкладки может совпасть с заголовком экрана). */
export async function tabEl(app, name) {
  const els = await app.findAll(tab(name));
  assert(els.length, `вкладка «${name}» видна`);
  const rects = await Promise.all(els.map((e) => e.rect()));
  let best = 0;
  rects.forEach((r, i) => { if (r.y > rects[best].y) best = i; });
  return { el: els[best], rect: rects[best] };
}

export async function openTab(app, name) {
  const { el } = await tabEl(app, name);
  await el.click();
}

/** Шаг 1 подготовки к мониторингу «בדיקת בטיחות» → «המשך». Звук тестового сигнала громкий (в т.ч. в беззвучном режиме). */
export async function passSafetyCheck(app) {
  await onHome(app);
  await app.tap(by.begins('התחלת ניטור'), { what: '«התחלת ניטור» на בית' });
  const volume = await app.findAll(by.begins('עוצמת צפצוף מקסימלית'));
  if (volume.length) await volume[0].click();
  if (await app.exists(by.exact('השמעה'))) {
    await app.tap(by.exact('השמעה'));
    await app.tap(by.exact('שמעתי'), { what: '«שמעתי» после тестового сигнала' });
  }
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на «בדיקת בטיחות»' });
  const end = Date.now() + 20000;
  while (!(await next.enabled())) {
    if (Date.now() > end) throw new Error('ПРЕДУСЛОВИЕ: «המשך» на «בדיקת בטיחות» неактивна (громкость, разрешения, сеть; один телефон в аккаунте после #4a869b — только предупреждение, не блок) — исправить на телефоне и перезапустить');
    await new Promise((r) => setTimeout(r, 300));
  }
  await next.click();
}

/** Открыть шаг 1 «בדיקת בטיחות» (без прохождения) и дождаться счётчика «N מתוך 5» — проверки закончились. */
export async function openSafetyCheck(app) {
  await onHome(app);
  await app.tap(by.begins('התחלת ניטור'), { what: '«התחלת ניטור» на בית' });
  await app.waitFor(by.contains('בדיקת בטיחות'), { timeout: 20000, what: 'экран «בדיקת בטיחות»' });
  return app.waitFor(by.contains('מתוך 5'), { timeout: 30000, what: 'счётчик «N מתוך 5» на «בדיקת בטיחות»' });
}

/** Ждёт, пока кнопка станет enabled === want (опрос результата, без фиксированной паузы). */
export async function waitEnabled(el, want, { timeout = 15000, what = 'кнопка' } = {}) {
  const end = Date.now() + timeout;
  let s;
  while (Date.now() < end) {
    s = await el.enabled();
    if (s === want) return;
    await new Promise((r) => setTimeout(r, 300));
  }
  throw new Error(`Проверка не прошла: ${what} — ожидалось ${want ? 'активна' : 'неактивна (серая)'}, сейчас ${s ? 'активна' : 'неактивна'}`);
}

/** Страница https://banci.expo.app/about (#94e4f3) — тексты, видимые во встроенном браузере как StaticText. */
export const ABOUT_TITLE = 'השגחה חכמה על הבריכה';
export const ABOUT_SECTIONS = ['איך זה עובד', 'מתי מגיעה התרעה', 'ברגע של חירום', 'אחרי הניטור', 'פרטיות', 'חשוב לדעת'];
/** Кнопка закрытия SFSafariViewController — название зависит от языка телефона. */
const SAFARI_VC_CLOSE = `type == "XCUIElementTypeButton" AND (name IN {"Закрыть","Готово","Close","Done","סגירה","סגור","סיום"} OR label IN {"Закрыть","Готово","Close","Done","סגירה","סגור","סיום"})`;

/** Проверка страницы /about во встроенном браузере: открыта внутри Banci (не Safari), заголовок, разделы, «לא תחליף להשגחה», ссылка на условия. */
export async function checkAboutPage(app) {
  await app.waitFor(by.contains(ABOUT_TITLE), { timeout: 30000, what: `страница /about — «${ABOUT_TITLE}» во встроенном браузере` });
  assert((await app.appState()) === 4, 'Banci на переднем плане (страница открыта во встроенном браузере)');
  assert((await app.appState('com.apple.mobilesafari')) !== 4, 'Safari не открыт поверх приложения');
  assert(await app.exists(SAFARI_VC_CLOSE), 'есть кнопка закрытия встроенного браузера');
  for (const s of ABOUT_SECTIONS) await app.scrollTo(by.contains(s), { max: 12, what: `раздел «${s}» на /about` });
  await app.scrollTo(by.contains('לא תחליף להשגחה'), { max: 6, what: '«לא תחליף להשגחה» в «חשוב לדעת»' });
  await app.scrollTo(by.contains('לתנאי השימוש המלאים'), { max: 6, what: 'ссылка «לתנאי השימוש המלאים»' });
}

/** Закрыть встроенный браузер (не нажимает ссылки страницы). */
export async function closeInAppBrowser(app) {
  await app.tap(SAFARI_VC_CLOSE, { what: 'кнопка закрытия встроенного браузера («Закрыть» / «Done»)' });
  await app.waitGone(by.contains(ABOUT_TITLE), { what: 'встроенный браузер со страницей /about' });
}

/** Шаг 2 «כוונו את המצלמה לבריכה» (#f7bfca): тексты подсказок над галочкой — при любой из них «המשך» серая. */
export const CAMERA_HINTS = [
  'משהו מכסה את עדשת המצלמה',
  'חשוך מדי',
  'נראה שחלק מהמים בקצה התמונה',
  'הקצה הרחוק של הבריכה לא בתמונה',
  'לא רואים מים',
  'חלק מהבריכה מוסתר',
  'הטלפון זז',
];
export const WATER_CHECKBOX = 'כל שטח המים נראה';

/** «בית» → «התחלת ניטור» → «בדיקת בטיחות» → «המשך» → шаг 2; возвращает чекбокс «כל שטח המים נראה בתמונה…». */
export async function openCameraStep(app) {
  await passSafetyCheck(app);
  return app.waitFor(by.begins(WATER_CHECKBOX), { timeout: 20000, what: 'чекбокс «כל שטח המים נראה בתמונה…» на шаге 2' });
}

/** Видимые сейчас подсказки шага камеры (тексты из CAMERA_HINTS). */
export async function visibleCameraHints(app) {
  const out = [];
  for (const h of CAMERA_HINTS) if (await app.exists(by.contains(h))) out.push(h);
  return out;
}

/** Превью камеры на шаге 2 и на «כוונו את המצלמה מחדש» (#f7bfca, #e946f4). Превью без имени доступности: самый высокий
 *  блок Other/Image высотой 25–70% экрана, ниже статус-бара и над инструкцией «גררו את ארבע הנקודות…»; при равной
 *  высоте — самый узкий (сам кадр, не обёртка). Возвращает { rect, W, H } или rect = null, если блок не найден. */
export const DRAG_POINTS_HINT = 'גררו את ארבע הנקודות לפינות שטח המים';
export async function cameraPreviewRect(app) {
  const { width: W, height: H } = await app.windowRect();
  const hint = await app.waitFor(by.contains(DRAG_POINTS_HINT), { what: 'инструкция «גררו את ארבע הנקודות…» под превью' });
  const hintTop = (await hint.rect()).y;
  const els = await app.findAll('type == "XCUIElementTypeOther" OR type == "XCUIElementTypeImage"');
  let best = null;
  for (const e of els) {
    const r = await e.rect();
    if (r.height < H * 0.25 || r.height > H * 0.7) continue;
    if (r.y + r.height > hintTop + 4 || r.y < H * 0.05) continue;
    if (!best || r.height > best.height || (r.height === best.height && r.width < best.width)) best = r;
  }
  return { rect: best, W, H, hintTop };
}

/** Проверка «превью от края до края» (Figma 07.3 → просьба клиента #e946f4): x ≤ 1 и x + ширина ≥ W − 1. */
export async function assertPreviewFullWidth(app, where) {
  const { rect, W, hintTop } = await cameraPreviewRect(app);
  assert(rect, `${where}: блок превью камеры найден над «גררו את ארבע הנקודות…» (y < ${hintTop})`);
  assert(rect.x <= 1 && rect.x + rect.width >= W - 1, `${where}: превью камеры на всю ширину: x=${rect.x}, ширина=${rect.width}, окно=${W}`);
  return rect;
}

/** RTL-выравнивание текста по rect (#50a708). Берёт самый верхний видимый элемент по predicate (заголовок выше
 *  одноимённой вкладки) и проверяет: правый край прижат к правой стороне экрана (x + ширина ≥ W − margin) и центр
 *  в правой половине (текст, прижатый влево, даёт центр < W/2). margin ≈ 40 pt для текста у края, больше — если справа
 *  иконка/аватар (строки «חשבון», дети на шаге 3). rect на всю ширину (≥ 0.85·W) по координатам не различить —
 *  это ошибка отбора теста, а не баг: падение с пометкой «ОШИБКА ТЕСТА». */
export async function assertRightAligned(app, predicate, what, { margin = 40, el } = {}) {
  const { width: W } = await app.windowRect();
  let r;
  if (el) r = await el.rect();
  else {
    const els = await app.findAll(predicate);
    assert(els.length, `${what}: элемент виден`);
    const rects = await Promise.all(els.map((e) => e.rect()));
    r = rects.reduce((a, b) => (b.y < a.y ? b : a));
  }
  const right = r.x + r.width;
  const info = `x=${Math.round(r.x)}, w=${Math.round(r.width)}, правый край ${Math.round(right)}, экран ${W}`;
  if (r.width >= W * 0.85) throw new Error(`ОШИБКА ТЕСТА: ${what} — rect на всю ширину (${info}), выравнивание по координатам не определить; сверить по скриншоту и поправить отбор элемента`);
  assert(right >= W - margin, `${what} прижат вправо: правый край ≥ ${W - margin} (${info})`);
  assert(r.x + r.width / 2 > W / 2, `${what} в правой половине экрана (${info})`);
  return r;
}

/** Форма «תמיכה» (#39b1c8): «חשבון» → строка «תמיכה». Тексты — как в приложении 01.11. */
export const SUPPORT = {
  row: 'תמיכה',
  subjectLabel: 'נושא הפנייה',
  topics: ['תקלה', 'שאלה', 'אחר'],
  messageLabel: 'מה תרצו לספר לנו',
  limitHint: 'אפשר לכתוב עד 2000 תווים',
  send: 'שליחה',
  sent: 'הפנייה נשלחה',
};

export async function openSupport(app) {
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.exact(SUPPORT.row, 'StaticText'), { what: 'строка «תמיכה» в «חשבון»' });
  await row.click();
  return app.waitFor(by.contains(SUPPORT.subjectLabel, 'StaticText'), { what: 'форма «תמיכה» — «נושא הפנייה»' });
}

/** Сегмент темы на форме «תמיכה» (кнопка/элемент с точным текстом, не StaticText-подпись внутри — берём первый видимый). */
export function supportTopic(app, t) {
  return app.waitFor(by.exact(t), { what: `сегмент «${t}» на форме «תמיכה»` });
}

/** Выбран ли сегмент: атрибут selected, иначе value (נבחר / selected / 1). null — состояние Appium не видно. */
export async function segmentSelected(el) {
  const sel = String(await el.attr('selected').catch(() => ''));
  if (sel === 'true') return true;
  const v = String((await el.attr('value').catch(() => '')) ?? '').toLowerCase();
  if (/לא נבחר|not selected|unselected/.test(v)) return false;
  if (/נבחר|selected/.test(v) || v === '1') return true;
  if (sel === 'false') return false;
  return null;
}
